import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/BatchNormalization.html","title":"BatchNormalization","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":0.47,"words":140},"filePathRelative":"BatchNormalization.md"}`),a={name:`BatchNormalization.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="batchnormalization" tabindex="-1"><a class="header-anchor" href="#batchnormalization"><span>BatchNormalization</span></a></h1><p>バッチ正規化とも言う。<a href="./原論文から解き明かす生成AI.html">原論文から解き明かす生成AI</a>の<a href="./LayerNormalization.html">LayerNormalization</a>の項ででてきたのでメモしておく。</p><p>書籍、<a href="./深層学習.html">深層学習</a>のp136 （4.3.4）をベースに書く。</p><p>多層のニューラルネットにおいて、途中の層は前の層の変化に追従する事ばかりに学習の労力が割かれてなかなか学習が進まない問題（内部共変量シフト）が起こる事が知られていて、それに対する対策。</p><p>ミニバッチごとに平均と分散を割り引いた入力を入れるように変更する手法。</p><p><img src="/RandomThoughts/assets/0000-C2FpEyjr.png" alt="imgs/BatchNorm/0000.png"></p><p><a href="./LayerNormalization.html">LayerNormalization</a>との比較で調べていた感じ、どうもベータとガンマはベクトルでガンマとの積はelement-wiseっぽい。以下のWikipediaでもkの添字がある。</p><p><a href="https://en.wikipedia.org/wiki/Batch_normalization" target="_blank" rel="noopener noreferrer">Batch normalization - Wikipedia</a></p><p><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>σ</mi><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">\\sigma^2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">σ</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span> もベクトルで2乗は要素ごとに計算するっぽい。えー、この表記だと2乗ノルムだと思うよ〜。</p><h3 id="layernormlizationとの比較" tabindex="-1"><a class="header-anchor" href="#layernormlizationとの比較"><span>LayerNormlizationとの比較</span></a></h3><p>ミニバッチ単位で計算するのでバッチが必要だ、というのは大前提として。</p><p><a href="./LayerNormalization.html">LayerNormalization</a>との比較としては、こちらは<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>μ</mi></mrow><annotation encoding="application/x-tex">\\mu</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">μ</span></span></span></span>がベクトルで要素ごとに別々というのはちょっと注目したい所。</p><p>また、inference時には平均の計算は不要というのも速度という点では意外と良いらしい。</p>`,13)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};